// Modelos 3D embutidos (ferrari.glb e Soldier.glb) em base64
  // (ficam dentro do arquivo, então não precisam de internet nem de arquivos extras)
  window.EMBEDDED_MODELS = {
    rival: "",
    character: ""
  };

  // Diagnóstico: mostra erros na tela em vez de deixar tudo preto
  window.showPageError = function (msg) {
    document.getElementById('errorMsg').textContent = msg || '';
    document.getElementById('errorHint').textContent =
      'Verifique a conexão com a internet (o Three.js é carregado de um CDN) e tente novamente.';
    document.getElementById('error').style.display = 'flex';
  };
  window.addEventListener('error', e => window.showPageError(e.message));
  window.addEventListener('unhandledrejection', e => window.showPageError(String(e.reason)));
  setTimeout(() => {
    if (!window.gameReady) {
      window.showPageError('O jogo não iniciou em 12 segundos. Provavelmente o Three.js não foi carregado do CDN.');
    }
  }, 12000);
